mapper.select:
SELECT DISTINCT CHRT.ORG_ID AS orgId , ORG.ORGNM AS orgnm FROM TB_LMS_ATNDLC E JOIN TB_LMS_SBJCT A ON A.SBJCT_ID = E.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = CHRT.ORG_ID WHERE E.USER_ID = #{userId} AND E.ATNDLC_STSCD = 'APPROVE' AND NVL(A.DELYN,'N') = 'N' AND A.SBJCT_YR = #{searchYr}
AND CHRT.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
ORDER BY orgnm ASC

SELECT MIN(CHRT.SMSTR_CHRT_ID) AS smstrChrtId , CHRT.DGRS_YR AS dgrsYr , CHRT.DGRS_SMSTR_CHRT AS dgrsSmstrChrt , MIN(CHRT.SMSTR_CHRTNM) AS smstrChrtnm FROM TB_LMS_ATNDLC E JOIN TB_LMS_SBJCT A ON A.SBJCT_ID = E.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID WHERE E.USER_ID = #{userId} AND E.ATNDLC_STSCD = 'APPROVE' AND NVL(A.DELYN,'N') = 'N' AND A.SBJCT_YR = #{searchYr}
AND CHRT.ORG_ID = #{searchOrgId}
GROUP BY CHRT.DGRS_YR, CHRT.DGRS_SMSTR_CHRT ORDER BY CHRT.DGRS_YR DESC, CHRT.DGRS_SMSTR_CHRT DESC

SELECT COUNT(*)
FROM TB_LMS_ATNDLC E
JOIN TB_LMS_SBJCT A
ON A.SBJCT_ID = E.SBJCT_ID
JOIN TB_LMS_SMSTR_CHRT CHRT
ON CHRT.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID
WHERE E.USER_ID = #{userId}
AND E.ATNDLC_STSCD = 'APPROVE'
AND NVL(A.DELYN,'N') = 'N'
AND A.SBJCT_YR = #{searchYr}

    AND CHRT.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}


    AND CHRT.ORG_ID = #{searchOrgId}


    AND A.SBJCT_ID = #{searchSbjctId}

SELECT * FROM ( SELECT ROWNUM AS RNUM, X.* FROM ( SELECT ROW_NUMBER() OVER( ORDER BY A.SBJCT_YR DESC, TRIM(A.SBJCT_SMSTR) DESC, A.SBJCTNM ASC, A.DVCLAS_NO ASC ) AS LINE_NO , A.SBJCT_ID AS SBJCT_ID , A.SBJCT_YR AS SBJCT_YR , TRIM(A.SBJCT_SMSTR) AS SBJCT_SMSTR , O.ORGNM AS ORG_NM , A.SBJCTNM AS SBJCTNM , TO_CHAR(A.DVCLAS_NO) AS DVCLAS_NO , A.CRDTS AS CRDTS , ( SELECT LISTAGG(U2.USERNM, ', ') WITHIN GROUP (ORDER BY SA.SBJCT_ADM_SEQNO) FROM TB_LMS_SBJCT_ADM SA JOIN TB_LMS_USER U2 ON U2.USER_ID = SA.USER_ID WHERE SA.SBJCT_ID = A.SBJCT_ID AND SA.SBJCT_ADM_TYCD = 'COPROF' ) AS CO_PROF_NM , ( SELECT LISTAGG(U2.USERNM, ', ') WITHIN GROUP (ORDER BY SA.SBJCT_ADM_SEQNO) FROM TB_LMS_SBJCT_ADM SA JOIN TB_LMS_USER U2 ON U2.USER_ID = SA.USER_ID WHERE SA.SBJCT_ID = A.SBJCT_ID AND SA.SBJCT_ADM_TYCD = 'TUT' ) AS TUTOR_NM , ( SELECT LISTAGG(U2.USERNM, ', ') WITHIN GROUP (ORDER BY SA.SBJCT_ADM_SEQNO) FROM TB_LMS_SBJCT_ADM SA JOIN TB_LMS_USER U2 ON U2.USER_ID = SA.USER_ID WHERE SA.SBJCT_ID = A.SBJCT_ID AND SA.SBJCT_ADM_TYCD = 'ASSI' ) AS ASST_NM FROM TB_LMS_ATNDLC E JOIN TB_LMS_SBJCT A ON A.SBJCT_ID = E.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG O ON O.ORG_ID = CHRT.ORG_ID WHERE E.USER_ID = #{userId} AND E.ATNDLC_STSCD = 'APPROVE' AND NVL(A.DELYN,'N') = 'N' AND A.SBJCT_YR = #{searchYr}
AND CHRT.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND CHRT.ORG_ID = #{searchOrgId}
AND A.SBJCT_ID = #{searchSbjctId}
) X WHERE ROWNUM <= (#{firstIndex} + #{listScale}) ) WHERE RNUM > #{firstIndex}

SELECT DISTINCT A.SBJCT_ID AS sbjctId , A.SBJCTNM AS sbjctnm , TO_CHAR(A.DVCLAS_NO) AS dvclasNo FROM TB_LMS_ATNDLC E JOIN TB_LMS_SBJCT A ON A.SBJCT_ID = E.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID WHERE E.USER_ID = #{userId} AND E.ATNDLC_STSCD = 'APPROVE' AND NVL(A.DELYN,'N') = 'N' AND A.SBJCT_YR = #{searchYr}
AND CHRT.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND CHRT.ORG_ID = #{searchOrgId}
ORDER BY sbjctnm ASC, dvclasNo ASC

SELECT COUNT(*)
FROM TB_LMS_LOG_USER_ACTV L
WHERE L.SBJCT_ID = #{sbjctId}
AND L.USER_ID = #{userId}
AND EXISTS (
SELECT 1
FROM TB_LMS_ATNDLC A
WHERE A.USER_ID = L.USER_ID
AND A.SBJCT_ID = #{sbjctId}
AND A.ATNDLC_STSCD = 'APPROVE'
)

    AND (
    L.USER_REQ_URL LIKE '%' || #{keyword} || '%'
    OR NVL(L.CNTN_BRWSR, L.REQ_TYCD) LIKE '%' || #{keyword} || '%'
    OR L.CNTN_IP LIKE '%' || #{keyword} || '%'
    )

SELECT * FROM ( SELECT ROWNUM AS RNUM, X.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY L.ACTV_DTTM DESC) AS LINE_NO , TO_CHAR(TO_DATE(L.ACTV_DTTM,'YYYYMMDDHH24MISS'),'YYYY.MM.DD HH24:MI:SS') AS ACT_DTTM , L.USER_REQ_URL AS ACT_CONTS , NVL(L.CNTN_BRWSR, L.REQ_TYCD) AS DEVICE_NM , L.CNTN_IP AS IP_ADDR FROM TB_LMS_LOG_USER_ACTV L WHERE L.SBJCT_ID = #{sbjctId} AND L.USER_ID = #{userId} AND EXISTS ( SELECT 1 FROM TB_LMS_ATNDLC A WHERE A.USER_ID = L.USER_ID AND A.SBJCT_ID = #{sbjctId} AND A.ATNDLC_STSCD = 'APPROVE' )
AND ( L.USER_REQ_URL LIKE '%' || #{keyword} || '%' OR NVL(L.CNTN_BRWSR, L.REQ_TYCD) LIKE '%' || #{keyword} || '%' OR L.CNTN_IP LIKE '%' || #{keyword} || '%' )
ORDER BY L.ACTV_DTTM DESC ) X WHERE ROWNUM <= (#{firstIndex} + #{listScale}) ) WHERE RNUM > #{firstIndex}
